#include <glm/glm.hpp>

struct Particle
{
    glm::vec3 position, velocity, acceleration, force;
    float density;
};

glm::ivec3 getCell(Particle *p, float h)
{
    return glm::ivec3(p->position.x / h, p->position.y / h, p->position.z / h);
}

